        pai = new("/d/tulong/obj/duan1");
        pai->move(this_player());
        pai = new("/d/tulong/obj/duan2");
        pai->move(this_player());
        pai = new("/d/tulong/obj/zhenjing");
        pai->move(this_player());
        pai = new("/d/tulong/obj/miji");
        pai->move(this_player());
        pai = new("/d/tulong/obj/yishu");
