        me->query("family/master_name") == "东方不败") {
        command("ah");
        command("say 原来是东方教主的弟子，兴会，兴会！");
        command("say 这件事非同小可，我做不了主，你还是去找几位庄主吧。");
        me->set("move_party/日月神教--梅庄", 1);
        return;
    }

    if ((int)me->query("shen") > 1000) {
        command("heng");
        command("say 我们孤山梅庄向来不问江湖事，也不结交你这样的侠义之士。");
        return;
    }

    if ((int)me->query("shen") < -1000) {
        command("heng");
