    return 1;
}

int repairing_2(object me, object ob) {
    if (!present(ob, environment())) return 1;

    if (ob->query("damaged")) {
        message_vision(GRN "\n道果禅师对着木人瞧了一会，又试着扳动木人的四肢和脑袋，嘴里喃喃念叨着什么。\n\n" NOR, me);
