    if (!present(ob, who)) return notify_fail("你没有这件东西。\n");

    if (is_busy()) {
        command("say 慢慢来，急什么！");
        return 0;
    }

    if ((string)ob->query("id") != "fushe dan"
        && (string)ob->query("id") != "baixiang hua")
        return notify_fail("许雪亭摇头道：如果杀不了洪安通，给我什么也没用啊。。。\n");

